-- Table: hrm_payroll_run
-- Source: accounting_admin_db.sql (7. HRMIS)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS hrm_payroll_run (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    payroll_number    VARCHAR(50) NOT NULL UNIQUE,
    period_code       VARCHAR(7) NOT NULL,
    payroll_date      DATE NOT NULL,
    status            VARCHAR(20) NOT NULL DEFAULT 'draft'
                      CHECK (status IN ('draft', 'created', 'approved', 'rejected', 'pending', 'completed', 'reopen')),
    total_gross       NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (total_gross >= 0),
    total_deductions  NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (total_deductions >= 0),
    total_net         NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (total_net >= 0),
    notes             TEXT,
    prepared_by       BIGINT REFERENCES masterdata_user(id),
    approved_by       BIGINT REFERENCES masterdata_user(id),
    approved_at       TIMESTAMPTZ,
    posted_by         BIGINT REFERENCES masterdata_user(id),
    posted_at         TIMESTAMPTZ,
    journal_id        BIGINT REFERENCES accounting_journal(id),
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at        TIMESTAMPTZ NOT NULL DEFAULT now()
);
